@Test
void createOrdersWithOppositeItemOrderFinishWithinTwoSeconds() {
    InventoryService inventory = new InventoryService();
    inventory.register(10, 2);
    inventory.register(22, 2);
    OrderService service = new OrderService(inventory);

    ExecutorService executor = Executors.newFixedThreadPool(2);
    CountDownLatch start = new CountDownLatch(1);

    try {
        assertTimeoutPreemptively(Duration.ofSeconds(2), () -> {
            Future<Order> first = executor.submit(() -> {
                start.await();
                return service.createOrder(1L, List.of(
                        new OrderItem(10, 1), new OrderItem(22, 1)));
            });
            Future<Order> second = executor.submit(() -> {
                start.await();
                return service.createOrder(2L, List.of(
                        new OrderItem(22, 1), new OrderItem(10, 1)));
            });

            start.countDown();
            first.get();
            second.get();
        });
    } finally {
        executor.shutdownNow();
    }
}
